import React, {useEffect, useRef, useState} from 'react';
import './workspace.css';
export type Item = {id: string; title: string};
export function ListWorkspace({load, onCreate}: {load: (signal: AbortSignal) => Promise<Item[]>; onCreate: () => void}) {
 const [items, setItems] = useState<Item[] | null>(null); const [busy, setBusy] = useState(true); const [error, setError] = useState<string | null>(null); const [attempt, setAttempt] = useState(0); const request = useRef(0);
 useEffect(() => {const controller = new AbortController(); const version = ++request.current; setBusy(true); setError(null); load(controller.signal).then(result => {if (!controller.signal.aborted && version === request.current) setItems(result);}).catch(() => {if (!controller.signal.aborted && version === request.current) setError('Could not load the list. Check your connection and try again.');}).finally(() => {if (!controller.signal.aborted && version === request.current) setBusy(false);}); return () => controller.abort();}, [load, attempt]);
 return <section className="list-workspace" aria-labelledby="list-title"><header><h1 id="list-title">Items</h1><button disabled={busy} onClick={() => setAttempt(value => value + 1)}>Refresh</button></header><p role="status" aria-live="polite">{busy ? items === null ? 'Loading items…' : 'Refreshing… Your current items remain available.' : !error && items ? `${items.length} items loaded.` : ''}</p>{error && <div className="list-error" role="alert"><strong>Unable to update items</strong><p>{error}</p>{items !== null && <p>Showing the last successfully loaded results.</p>}<button onClick={() => setAttempt(value => value + 1)}>Try again</button></div>}<div aria-busy={busy}>{items !== null && (items.length ? <ul>{items.map(item => <li key={item.id}>{item.title}</li>)}</ul> : <div className="empty-list"><h2>No items yet</h2><p>Create an item to start your workspace.</p><button onClick={onCreate}>Create item</button></div>)}</div></section>;
}
